export default function ProductImage({ name, basePath = '/images/optimized' }) {
    return (
        <picture>
            <source type="image/webp" srcSet={`${basePath}/${name}-400.webp 400w, ${basePath}/${name}-800.webp 800w, ${basePath}/${name}-1200.webp 1200w`} sizes="(max-width:600px) 100vw, 600px" />
            <img src={`${basePath}/${name}-800.jpg`} srcSet={`${basePath}/${name}-400.jpg 400w, ${basePath}/${name}-800.jpg 800w, ${basePath}/${name}-1200.jpg 1200w`} alt={name} loading="lazy" />
        </picture>
    );
}

export default function ProductImage({ id, base='/images/optimized' }) {
  return (
    <picture>
      <source type="image/webp" srcSet={`${base}/${id}-400.webp 400w, ${base}/${id}-800.webp 800w, ${base}/${id}-1200.webp 1200w`} sizes="(max-width:600px) 100vw, 600px" />
      <img src={`${base}/${id}-800.jpg`} srcSet={`${base}/${id}-400.jpg 400w, ${base}/${id}-800.jpg 800w, ${base}/${id}-1200.jpg 1200w`} alt="" loading="lazy" />
    </picture>
  )
}
